        this.data = new java.util.HashMap<>();
        data.forEach((key, value) -> this.data.put(key, value));
    }

    public static MapAdapter mockMap(String key, String value) {
        return new MapAdapter(new java.util.HashMap<>().put(key, value));
    }
}

